package com.youkia.iaa.collection;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.youkia.iaa.api.ApiException;
import org.springframework.dao.EmptyResultDataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.RestClient;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;

/** Real public Apple RSS ingest. It records ranking evidence but never invents IAA. */
@Service
public class AppleRssCollectionService {
    private final JdbcTemplate jdbc; private final ObjectMapper mapper; private final RestClient client=RestClient.builder().baseUrl("https://rss.applemarketingtools.com").defaultHeader("User-Agent","iaa-radar-public-source/1.0").defaultHeader("Accept","application/json").build();
    public AppleRssCollectionService(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}
    @Transactional
    public Map<String,Object> collect(String country, LocalDate businessDate, int limit){
        String cc=country==null?"cn":country.toLowerCase(Locale.ROOT);if(!Set.of("cn","us","gb","de","fr").contains(cc))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_COUNTRY","只支持 cn/us/gb/de/fr");
        int top=Math.min(Math.max(limit,1),100);String path="/api/v2/"+cc+"/apps/top-free/"+top+"/apps.json";String raw;try{raw=client.get().uri(path).retrieve().body(String.class);}catch(Exception e){throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"APPLE_RSS_UNAVAILABLE","Apple RSS 当前不可访问");}
        return ingest(cc,businessDate,top,raw,path);
    }
    @Transactional
    public Map<String,Object> collectMaterial(String country, LocalDate businessDate, int limit, String raw){String cc=country==null?"cn":country.toLowerCase(Locale.ROOT);int top=Math.min(Math.max(limit,1),100);return ingest(cc,businessDate,top,raw,"/api/v2/"+cc+"/apps/top-free/"+top+"/apps.json");}
    private Map<String,Object> ingest(String cc,LocalDate businessDate,int top,String raw,String path){
        try{if(raw==null||raw.isBlank())throw new IllegalArgumentException("empty response");JsonNode root=mapper.readTree(raw),results=root.path("feed").path("results");if(!results.isArray())throw new IllegalArgumentException();LocalDate date=businessDate==null?LocalDate.now(ZoneId.of("Asia/Shanghai")):businessDate;long source=source();long chart=chart(source,cc);long job=job(source);String sha=sha256(raw);String key="apple-rss:"+cc+":"+date+":"+top+":"+sha;Long existing=existingSnapshot(chart,date,sha);if(existing!=null)return result(existing,chart,date,results.size(),true,sha);
            long run=run(job,date,key);int rank=1;List<Long> versionIds=new ArrayList<>();for(JsonNode n:results){String external=n.path("id").asText(null);if(external==null||external.isBlank()){rank++;continue;}String name=n.path("name").asText("未命名应用");long product=product(external,name);long version=version(product,external,name);versionIds.add(version);long entrySnapshotPlaceholder=0;ensureEvidence(version,source,external,rank,name,path,date);rank++;}
            long snapshot=insertSnapshot(chart,run,date,top,results.size(),path,sha);rank=1;for(JsonNode n:results){String external=n.path("id").asText(null);if(external!=null&&!external.isBlank()){long version=versionId(external);jdbc.update("INSERT INTO ranking_entry(snapshot_id,platform_version_id,rank_position,source_metrics) VALUES(?,?,?,?)",snapshot,version,rank,"{\"source\":\"APPLE_PUBLIC_RSS\",\"estimated\":false}");}rank++;}
            jdbc.update("UPDATE collection_run SET status='SUCCEEDED',stage='PUBLISHED',finished_at=?,heartbeat_at=?,metrics=? WHERE id=?",now(),now(),"{\"entries\":"+results.size()+",\"mode\":\"LIVE_PUBLIC\"}",run);return result(snapshot,chart,date,results.size(),false,sha);
        }catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"APPLE_RSS_INGEST_FAILED","Apple RSS 数据解析或写入失败："+e.getMessage());}
    }
    private Map<String,Object> result(long snapshot,long chart,LocalDate date,int count,boolean reused,String sha){return Map.of("mode","LIVE_PUBLIC","source","Apple Marketing Tools RSS","snapshotId",String.valueOf(snapshot),"chartId",String.valueOf(chart),"businessDate",date,"entries",count,"reused",reused,"rawSha256",sha,"monetization","UNKNOWN","warning","公开免费 App 榜；未提供版本级 IAA 证据，不进入 PURE_IAA 精选");}
    private long source(){try{return jdbc.queryForObject("SELECT id FROM data_source WHERE adapter_key='apple-rss-public' LIMIT 1",Long.class);}catch(EmptyResultDataAccessException e){jdbc.update("INSERT INTO data_source(name,adapter_key,access_method,enabled,secret_ref,config,authorization_notes,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)","Apple RSS 公开源","apple-rss-public","PUBLIC_API",true,null,"{\"host\":\"rss.applemarketingtools.com\"}","公开 RSS；排名可验证，IAA 不提供；仅保存字段和哈希",0,now(),now());return jdbc.queryForObject("SELECT id FROM data_source WHERE adapter_key='apple-rss-public' LIMIT 1",Long.class);}}
    private long chart(long source,String cc){try{return jdbc.queryForObject("SELECT id FROM chart_definition WHERE source_id=? AND platform='IOS' AND region=? AND external_chart_id=?",Long.class,source,cc.toUpperCase(Locale.ROOT),"apple-public-top-free");}catch(EmptyResultDataAccessException e){jdbc.update("INSERT INTO chart_definition(source_id,platform,region,external_chart_id,name,kind,category_key,device_scope,requested_top_n,enabled,methodology,config) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",source,"IOS",cc.toUpperCase(Locale.ROOT),"apple-public-top-free","Apple 公开免费 App 排行","HEAT","ALL","DEFAULT",100,true,"Apple Marketing Tools RSS；非完整游戏榜","{\"public\":true,\"persisted\":true}");return jdbc.queryForObject("SELECT id FROM chart_definition WHERE source_id=? AND platform='IOS' AND region=? AND external_chart_id=?",Long.class,source,cc.toUpperCase(Locale.ROOT),"apple-public-top-free");}}
    private long job(long source){try{return jdbc.queryForObject("SELECT id FROM collection_job WHERE source_id=? AND name=?",Long.class,source,"Apple RSS public daily");}catch(EmptyResultDataAccessException e){jdbc.update("INSERT INTO collection_job(source_id,name,schedule_spec,timezone,enabled,config,version) VALUES(?,?,?,?,?,?,?)",source,"Apple RSS public daily","manual","Asia/Shanghai",false,"{\"mode\":\"LIVE_PUBLIC\"}",0);return jdbc.queryForObject("SELECT id FROM collection_job WHERE source_id=? AND name=?",Long.class,source,"Apple RSS public daily");}}
    private long run(long job,LocalDate date,String key){try{jdbc.update("INSERT INTO collection_run(job_id,business_date,run_mode,status,stage,idempotency_key,started_at,heartbeat_at,model_metadata) VALUES(?,?,?,?,?,?,?,?,?)",job,date,"LIVE_PUBLIC","RUNNING","FETCHED",key,now(),now(),"{\"provider\":\"none\"}");return jdbc.queryForObject("SELECT id FROM collection_run WHERE idempotency_key=?",Long.class,key);}catch(Exception e){Long id=jdbc.queryForObject("SELECT id FROM collection_run WHERE idempotency_key=?",Long.class,key);if(id!=null)return id;throw e;}}
    private long insertSnapshot(long chart,long run,LocalDate date,int top,int count,String url,String sha){int revision=Optional.ofNullable(jdbc.queryForObject("SELECT MAX(revision) FROM ranking_snapshot WHERE chart_id=? AND business_date=?",Integer.class,chart,date)).orElse(0)+1;jdbc.update("INSERT INTO ranking_snapshot(chart_id,run_id,business_date,source_date,revision,status,completeness,requested_top_n,covered_top_n,actual_count,source_url,raw_locator,raw_sha256,captured_at,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",chart,run,date,date,revision,"PUBLISHED",count>=top?"COMPLETE":"PARTIAL",top,count,count,url,url,sha,now(),now());return jdbc.queryForObject("SELECT id FROM ranking_snapshot WHERE chart_id=? AND business_date=? AND raw_sha256=?",Long.class,chart,date,sha);}
    private Long existingSnapshot(long chart,LocalDate date,String sha){try{return jdbc.queryForObject("SELECT id FROM ranking_snapshot WHERE chart_id=? AND business_date=? AND raw_sha256=?",Long.class,chart,date,sha);}catch(EmptyResultDataAccessException e){return null;}}
    private long product(String external,String name){try{return jdbc.queryForObject("SELECT product_id FROM platform_version WHERE platform='IOS' AND external_id=?",Long.class,external);}catch(EmptyResultDataAccessException e){jdbc.update("INSERT INTO product(name,pool_state,first_observed_at,created_at,updated_at,version) VALUES(?,?,?,?,?,0)",name,"PENDING_IDENTIFICATION",now(),now(),now());return jdbc.queryForObject("SELECT id FROM product WHERE name=? ORDER BY id DESC LIMIT 1",Long.class,name);}}
    private long version(long product,String external,String name){try{return jdbc.queryForObject("SELECT id FROM platform_version WHERE platform='IOS' AND external_id=?",Long.class,external);}catch(EmptyResultDataAccessException e){jdbc.update("INSERT INTO platform_version(product_id,platform,external_id,name,first_observed_at,source_fields,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)",product,"IOS",external,name,now(),"{\"source\":\"APPLE_PUBLIC_RSS\"}",now(),now());return versionId(external);}}
    private long versionId(String external){return jdbc.queryForObject("SELECT id FROM platform_version WHERE platform='IOS' AND external_id=?",Long.class,external);}
    private void ensureEvidence(long version,long source,String external,int rank,String name,String path,LocalDate date){try{jdbc.queryForObject("SELECT id FROM evidence WHERE platform_version_id=? AND source_record_id=? AND kind='PUBLIC_RANKING'",Long.class,version,external);return;}catch(EmptyResultDataAccessException ignored){}jdbc.update("INSERT INTO evidence(platform_version_id,source_id,kind,source_url,source_record_id,locator,raw_sha256,excerpt,observed_at,scope,metadata,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",version,source,"PUBLIC_RANKING","https://rss.applemarketingtools.com"+path,external,"feed.results["+(rank-1)+"]","",name+" rank "+rank,now(),"{\"businessDate\":\""+date+"\"}","{\"public\":true,\"noIaa\":true}","apple-rss",now());}
    private LocalDateTime now(){return LocalDateTime.now(ZoneOffset.UTC);} private String sha256(String s)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}
}
